            .for_each(|(chunk_idx, out_chunk)| {
                let base_row = chunk_idx * chunk_rows;
                for (j, out) in out_chunk.iter_mut().enumerate() {
                    matmul_prefetch_row(mapped, data_offset, row_size, base_row + j, d);
